// ticket_ids.cpp - issues ticket ids per queue using static local state.
// The program is a direct translation of ticket_ids.c to modern C++17,
// preserving all observable behaviour (output, formatting, exit code).

#include <cstdio>   // for printf, snprintf
#include <iostream> // for std::cin
#include <string>   // for std::string
#include <array>    // for std::array

// Generates the next ticket id.
// Static local variable keeps state across calls.
static int next_id()
{
    static int id = 1000;
    id += 7;
    return id;
}

// Produces a tag string based on the queue name and a call counter.
// The tag is stored in a static buffer so the returned pointer remains valid.
static const char* tag(const char* queue)
{
    static char buf[32];
    static int calls = 0;
    ++calls;
    // Use snprintf to avoid buffer overrun.
    std::snprintf(buf, sizeof(buf), "%c%c-%02d",
                  queue[0],
                  queue[1] ? queue[1] : 'X',
                  calls % 100);
    return buf;
}

int main()
{
    std::string q;
    std::array<int, 3> per_queue{0, 0, 0};

    // Read queue names until EOF.
    while (std::cin >> q) {
        const char* t1 = tag(q.c_str());

        int idx = (q[0] == 'a') ? 0
              : (q[0] == 'b') ? 1
              : 2;          // any other first character

        ++per_queue[idx];

        printf("%s %d (queue %d, #%d)\n",
               t1,
               next_id(),
               idx,
               per_queue[idx]);
    }

    printf("totals %d %d %d\n",
           per_queue[0],
           per_queue[1],
           per_queue[2]);

    return 0;
}
